package knowledgequery

import (
 "context"
 "crypto/sha256"
 "encoding/hex"
 "encoding/json"
 "errors"
 "os"
 "path/filepath"
 "reflect"
 "testing"
 "time"

 "github.com/qingwo1991-debug/ai-novel-writer-web/backend-go/internal/knowledgecopy"
 "github.com/qingwo1991-debug/ai-novel-writer-web/backend-go/internal/knowledgedomain"
)
func queryBudget()knowledgecopy.Budget{return knowledgecopy.Budget{MaxMetadataBytes:1024*1024,MaxCopies:100}}
func queryField(name,kind string)knowledgedomain.Field{return knowledgedomain.Field{Name:name,Type:kind}}
func queryFixture(t *testing.T)(knowledgedomain.Snapshot,*os.Root,string){t.Helper();path:=t.TempDir();if err:=os.Chmod(path,0700);err!=nil{t.Fatal(err)};root,err:=os.OpenRoot(path);if err!=nil{t.Fatal(err)};t.Cleanup(func(){root.Close()});docSchema:=[]knowledgedomain.Field{queryField("id","utf8"),queryField("fileName","utf8"),queryField("importedAt","utf8"),queryField("chunkCount","int32"),queryField("filePath","utf8"),queryField("corpusKind","utf8")};chunksSchema:=[]knowledgedomain.Field{queryField("id","utf8"),queryField("docId","utf8"),queryField("fileName","utf8"),queryField("text","utf8"),queryField("chunkIndex","int32"),queryField("totalChunks","int32"),queryField("importedAt","utf8"),queryField("corpusKind","utf8")};snapshot:=knowledgedomain.Snapshot{Tables:[]knowledgedomain.Table{{Name:"documents",Version:1,Schema:docSchema,Records:[]map[string]any{{"id":"doc-星海🙂","fileName":"source.txt","importedAt":"2026-01-01","chunkCount":json.Number("2"),"filePath":"knowledge-copy:IGNORED","corpusKind":"reference"}}},{Name:"chunks",Version:1,Schema:chunksSchema,Records:[]map[string]any{{"id":"first","docId":"doc-星海🙂","fileName":"source.txt","text":"indexed one","chunkIndex":0,"totalChunks":2,"importedAt":"2026-01-01","corpusKind":"reference"},{"id":"second","docId":"doc-星海🙂","fileName":"source.txt","text":"indexed two","chunkIndex":1,"totalChunks":2,"importedAt":"2026-01-01","corpusKind":"reference"}}}}};return snapshot,root,path}
func queryCopy(t *testing.T,path,id,content string,edited,dirty,mismatch bool){t.Helper();dir:=filepath.Join(path,"knowledge-copies");if err:=os.MkdirAll(dir,0700);err!=nil{t.Fatal(err)};sum:=sha256.Sum256([]byte(id));bodySum:=sha256.Sum256([]byte(content));indexed:=hex.EncodeToString(bodySum[:]);if mismatch{indexed="old"};raw,err:=json.Marshal(map[string]any{"content":content,"indexedHash":indexed,"edited":edited,"indexDirty":dirty});if err!=nil{t.Fatal(err)};if err:=os.WriteFile(filepath.Join(dir,hex.EncodeToString(sum[:])+".json"),raw,0600);err!=nil{t.Fatal(err)}}
func queryView(t *testing.T,snapshot knowledgedomain.Snapshot,root *os.Root)*View{t.Helper();v,err:=New(context.Background(),snapshot,root,queryBudget());if err!=nil{t.Fatal(err)};return v}
func TestQueryFourReadShapes(t *testing.T){snapshot,root,path:=queryFixture(t);queryCopy(t,path,"doc-星海🙂","Full original\nΩ🙂",true,false,false);view:=queryView(t,snapshot,root);docs,err:=view.Documents(context.Background());if err!=nil||len(docs)!=1||len(docs[0])!=6||docs[0]["corpusKind"]!="reference"||docs[0]["chunkCount"]!=int64(2){t.Fatal(docs,err)};stats,err:=view.Stats(context.Background());if err!=nil||!reflect.DeepEqual(stats,map[string]any{"documentCount":1,"totalChunks":2,"vectorDimension":0}){t.Fatal(stats,err)};count,err:=view.VectorlessCount(context.Background());if err!=nil||count["count"]!=2{t.Fatal(count,err)};copy,err:=view.ReadCopy(context.Background(),"doc-星海🙂");if err!=nil||len(copy)!=5||copy["available"]!=true||copy["content"]!="Full original\nΩ🙂"||copy["edited"]!=true||copy["indexStatus"]!="current"{t.Fatal(copy,err)}}
func TestQueryCopyStateMatrix(t *testing.T){for _,kind:=range []string{"missing","unmanaged","unknown","dirty","mismatch","edited-current","empty-current"}{t.Run(kind,func(t *testing.T){snapshot,root,path:=queryFixture(t);content:="original";if kind=="empty-current"{content=""};if kind!="missing"{queryCopy(t,path,"doc-星海🙂",content,true,kind=="dirty",kind=="mismatch")};id:="doc-星海🙂";if kind=="unmanaged"{snapshot.Tables[0].Records[0]["filePath"]="/synthetic/original.txt"};if kind=="unknown"{id="unknown"};view:=queryView(t,snapshot,root);copy,err:=view.ReadCopy(context.Background(),id);if err!=nil{t.Fatal(err)};if kind=="missing"||kind=="unmanaged"||kind=="unknown"{if !reflect.DeepEqual(copy,map[string]any{"available":false,"indexStatus":"unavailable"}){t.Fatal(copy)};return};status:="current";if kind=="dirty"||kind=="mismatch"{status="stale"};if copy["content"]!=content||copy["indexStatus"]!=status{t.Fatal(copy)}})}}
func queryAddSpace(t *testing.T,snapshot *knowledgedomain.Snapshot,rootPath,status string,count int,active bool){t.Helper();schema:=append([]knowledgedomain.Field(nil),snapshot.Tables[1].Schema...);schema=append(schema,knowledgedomain.Field{Name:"vector",Type:"fixed_size_list",ListSize:2,Children:[]knowledgedomain.Field{{Name:"item",Type:"float32",Nullable:true}}});table:=knowledgedomain.Table{Name:"chunks__space_1",Version:1,Schema:schema};for i:=0;i<count;i++{row:=map[string]any{};for key,value:=range snapshot.Tables[1].Records[i]{row[key]=value};row["vector"]=[]any{json.Number("0.25"),json.Number("0.5")};table.Records=append(table.Records,row)};snapshot.Tables=append(snapshot.Tables,table);var pointer any;if active{pointer=1};registry:=map[string]any{"version":1,"activeGeneration":pointer,"spaces":[]any{map[string]any{"generation":1,"tableName":"chunks__space_1","status":status,"vectorDimension":2,"modelFingerprint":"synthetic","createdAt":"synthetic","distanceMetric":"l2"}}};raw,err:=json.Marshal(registry);if err!=nil{t.Fatal(err)};snapshot.Registry=raw;if err:=os.WriteFile(filepath.Join(rootPath,"embedding-spaces.json"),raw,0600);err!=nil{t.Fatal(err)}}
func TestQueryActiveAndBuildingVectorless(t *testing.T){for _,kind:=range []string{"active","building","inactive"}{t.Run(kind,func(t *testing.T){snapshot,root,path:=queryFixture(t);count:=1;if kind=="active"{count=2};queryAddSpace(t,&snapshot,path,kind,count,kind=="active");view:=queryView(t,snapshot,root);stats,err:=view.Stats(context.Background());if err!=nil{t.Fatal(err)};missing,err:=view.VectorlessCount(context.Background());if err!=nil{t.Fatal(err)};dimension,wantMissing:=0,2;if kind=="active"{dimension,wantMissing=2,0};if kind=="building"{wantMissing=1};if stats["vectorDimension"]!=dimension||missing["count"]!=wantMissing{t.Fatal(stats,missing)}})}}
func TestQueryNoCanonicalTableStatsAreAllZero(t *testing.T){snapshot,root,_:=queryFixture(t);snapshot.Tables=snapshot.Tables[:1];snapshot.Tables[0].Records[0]["chunkCount"]=0;view:=queryView(t,snapshot,root);stats,_:=view.Stats(context.Background());docs,_:=view.Documents(context.Background());if len(docs)!=1||!reflect.DeepEqual(stats,map[string]any{"documentCount":0,"totalChunks":0,"vectorDimension":0}){t.Fatal(docs,stats)}}
func TestQueryEmptySnapshotAndFreshContainers(t *testing.T){_,root,_:=queryFixture(t);view:=queryView(t,knowledgedomain.Snapshot{},root);docs,err:=view.Documents(context.Background());if err!=nil||docs==nil||len(docs)!=0{t.Fatal(docs,err)};stats,_:=view.Stats(context.Background());stats["totalChunks"]=100;again,_:=view.Stats(context.Background());if again["totalChunks"]!=0{t.Fatal("stats borrowed map")}}
func TestQueryDoesNotBorrowOrRetainSource(t *testing.T){snapshot,root,path:=queryFixture(t);queryCopy(t,path,"doc-星海🙂","before",true,false,false);view:=queryView(t,snapshot,root);snapshot.Tables[0].Records[0]["id"]="changed";snapshot.Tables[0].Records[0]["chunkCount"]=900;snapshot.Tables[1].Records=nil;queryCopy(t,path,"doc-星海🙂","after",true,true,false);if err:=root.Close();err!=nil{t.Fatal(err)};docs,_:=view.Documents(context.Background());docs[0]["id"]="caller-mutated";again,_:=view.Documents(context.Background());copy,_:=view.ReadCopy(context.Background(),"doc-星海🙂");if again[0]["id"]!="doc-星海🙂"||again[0]["chunkCount"]!=int64(2)||copy["content"]!="before"{t.Fatal(again,copy)}}
func TestQueryDomainAndCopiedMetadataRejectBeforeView(t *testing.T){for _,kind:=range []string{"bad-domain","bad-copy","unsafe-root","invalid-budget"}{t.Run(kind,func(t *testing.T){snapshot,root,path:=queryFixture(t);budget:=queryBudget();switch kind{case "bad-domain":snapshot.Tables[1].Records[0]["docId"]="orphan";case "bad-copy":queryCopy(t,path,"orphan","x",false,false,false);if err:=os.WriteFile(filepath.Join(path,"knowledge-copies","bad.json"),[]byte("not-json"),0600);err!=nil{t.Fatal(err)};case "unsafe-root":if err:=os.Chmod(path,0755);err!=nil{t.Fatal(err)};case "invalid-budget":budget.MaxCopies=0};view,err:=New(context.Background(),snapshot,root,budget);if err==nil||view!=nil{t.Fatal(view,err)};if !errors.Is(err,ErrDomain)&&!errors.Is(err,ErrCopies){t.Fatal("raw error",err)}})}}
func TestQueryContextsAndNilViews(t *testing.T){snapshot,root,_:=queryFixture(t);if v,err:=New(nil,snapshot,root,queryBudget());v!=nil||!errors.Is(err,ErrInput){t.Fatal(v,err)};view:=queryView(t,snapshot,root);ctx,cancel:=context.WithCancel(context.Background());cancel();if v,err:=New(ctx,snapshot,root,queryBudget());v!=nil||!errors.Is(err,context.Canceled){t.Fatal(v,err)};deadline,stop:=context.WithDeadline(context.Background(),time.Unix(1,0));defer stop();for _,ctx:=range []context.Context{nil,ctx,deadline}{if value,err:=view.Documents(ctx);value!=nil||err==nil{t.Fatal(value,err)};if value,err:=view.Stats(ctx);value!=nil||err==nil{t.Fatal(value,err)};if value,err:=view.VectorlessCount(ctx);value!=nil||err==nil{t.Fatal(value,err)};if value,err:=view.ReadCopy(ctx,"doc");value!=nil||err==nil{t.Fatal(value,err)}};var nilView *View;if value,err:=nilView.Documents(context.Background());value!=nil||!errors.Is(err,ErrInput){t.Fatal(value,err)};if value,err:=nilView.Stats(context.Background());value!=nil||!errors.Is(err,ErrInput){t.Fatal(value,err)};if value,err:=nilView.VectorlessCount(context.Background());value!=nil||!errors.Is(err,ErrInput){t.Fatal(value,err)};if value,err:=nilView.ReadCopy(context.Background(),"id");value!=nil||!errors.Is(err,ErrInput){t.Fatal(value,err)};if _,err:=view.ReadCopy(context.Background(),string([]byte{255}));!errors.Is(err,ErrInput){t.Fatal(err)}}
